referenceSolutions.csharp:
public class Solution
{
    private static long Gcd(long a, long b)
    {
        while (b != 0) (a, b) = (b, a % b);
        return a;
    }

    public static long[] GcdAndLcm(int[] nums)
    {
        long g = nums[0], l = nums[0];
        for (var i = 1; i < nums.Length; i++)
        {
            long x = nums[i];
            g = Gcd(g, x);
            l = l / Gcd(l, x) * x; // divide first: l * x could overflow long even when the LCM fits
        }
        return new[] { g, l };
    }
}

referenceSolutions.python:
def gcd_and_lcm(nums):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    g = l = nums[0]
    for x in nums[1:]:
        g = gcd(g, x)
        l = l // gcd(l, x) * x  # Python can't overflow, but dividing first keeps numbers small
    return [g, l]
